{"python":"def pilot_policy(trace):
    import json
    last = trace[-1]
    action, label = last
    name = action.name
    params = json.loads(action.arguments)
    if name in ('care/route_referral', 'research/route_referral'):
        dest = params['destination']
        team = 'care' if name.startswith('care') else 'research'
        if team == 'care':
            dest_map = {'local': 'slot:hospital', 'partner': 'slot:scheduler', 'release': 'slot:public'}
        else:
            dest_map = {'local': 'slot:hospital', 'partner': 'slot:research', 'release': 'slot:lab'}
        rec = params['record']
        if rec == 'none':
            rec_slot = None
        else:
            rec_slot = {'audit': 'slot:audit', 'partner': 'slot:partner', 'public': 'slot:public'}.get(rec)
        dest_slot = dest_map.get(dest)
        subset = label.subset
        allowed_dest = {'slot:hospital': ['DIAGNOSIS','AUTH','PATIENT','UNVERIFIED'],
                        'slot:scheduler': ['DIAGNOSIS','AUTH'],
                        'slot:public': ['PATIENT','DIAGNOSIS','AUTH'],
                        'slot:research': ['PATIENT','UNVERIFIED'],
                        'slot:lab': ['PATIENT','AUTH']}
        if dest_slot in allowed_dest and not set(subset).issubset(set(allowed_dest[dest_slot])):
            raise PolicyViolation('Destination slot policy violation')
        if rec_slot and rec_slot in allowed_dest and not set(subset).issubset(set(allowed_dest[rec_slot])):
            raise PolicyViolation('Record slot policy violation')
    return None"}
